  // Audio Synthesizer
  function playTone(freq, duration, type = 'sine') {
    try {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (!AudioContext) return;
      const ctx = new AudioContext();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(freq, ctx.currentTime);
      gain.gain.setValueAtTime(0.1, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.start();
      osc.stop(ctx.currentTime + duration);
    } catch (e) {}
  }

  function playDoorSound() {
    playTone(320, 0.08, 'triangle');
    setTimeout(() => playTone(480, 0.12, 'triangle'), 80);
  }

  // Authentic Dual-Tone Elevator Chime (Ding-Dong)
  function playElevatorChime() {
    try {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (!AudioContext) return;
      const ctx = new AudioContext();
      // High bell (G5: 784 Hz)
      const osc1 = ctx.createOscillator();
      const gain1 = ctx.createGain();
      osc1.type = 'sine';
      osc1.frequency.setValueAtTime(784, ctx.currentTime);
      gain1.gain.setValueAtTime(0.2, ctx.currentTime);
      gain1.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.6);
      osc1.connect(gain1);
      gain1.connect(ctx.destination);
      osc1.start();
      osc1.stop(ctx.currentTime + 0.6);

      // Low bell (C5: 523 Hz)
      setTimeout(() => {
        try {
          const osc2 = ctx.createOscillator();
          const gain2 = ctx.createGain();
          osc2.type = 'sine';
          osc2.frequency.setValueAtTime(523, ctx.currentTime);
          gain2.gain.setValueAtTime(0.22, ctx.currentTime);
          gain2.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.8);
          osc2.connect(gain2);
          gain2.connect(ctx.destination);
          osc2.start();
          osc2.stop(ctx.currentTime + 0.8);
        } catch(err) {}
      }, 200);
    } catch(e) {}
  }

  // Polyphonic Windows XP Startup Chord Chime
  function playXPStartupChime() {
    try {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (!AudioContext) return;
      const ctx = new AudioContext();
      const chord = [
        { f: 155.56, t: 0, d: 2.0, g: 0.12 }, // Eb3
        { f: 233.08, t: 0.08, d: 1.9, g: 0.14 }, // Bb3
        { f: 311.13, t: 0.20, d: 1.8, g: 0.16 }, // Eb4
        { f: 392.00, t: 0.38, d: 1.7, g: 0.16 }, // G4
        { f: 466.16, t: 0.58, d: 1.6, g: 0.18 }, // Bb4
        { f: 622.25, t: 0.88, d: 2.2, g: 0.20 }, // Eb5
        { f: 783.99, t: 0.88, d: 2.0, g: 0.15 }  // G5
      ];
      chord.forEach(n => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(n.f, ctx.currentTime + n.t);
        gain.gain.setValueAtTime(0.001, ctx.currentTime + n.t);
        gain.gain.linearRampToValueAtTime(n.g, ctx.currentTime + n.t + 0.05);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + n.t + n.d);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(ctx.currentTime + n.t);
        osc.stop(ctx.currentTime + n.t + n.d);
      });
    } catch(e) {}
  }

  // Descending Windows XP Shutdown Sequence Chime
  function playXPShutdownChime() {
    try {
      const AudioContext = window.AudioContext || window.webkitAudioContext;
      if (!AudioContext) return;
      const ctx = new AudioContext();
      const seq = [
        { f: 622.25, t: 0, d: 0.45, g: 0.18 },    // Eb5
        { f: 466.16, t: 0.25, d: 0.45, g: 0.16 },  // Bb4
        { f: 415.30, t: 0.50, d: 0.55, g: 0.16 },  // Ab4
        { f: 311.13, t: 0.80, d: 1.60, g: 0.22 },  // Eb4
        { f: 155.56, t: 0.80, d: 1.60, g: 0.14 }   // Eb3
      ];
      seq.forEach(n => {
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();
        osc.type = 'triangle';
        osc.frequency.setValueAtTime(n.f, ctx.currentTime + n.t);
        gain.gain.setValueAtTime(0.001, ctx.currentTime + n.t);
        gain.gain.linearRampToValueAtTime(n.g, ctx.currentTime + n.t + 0.04);
        gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + n.t + n.d);
        osc.connect(gain);
        gain.connect(ctx.destination);
        osc.start(ctx.currentTime + n.t);
        osc.stop(ctx.currentTime + n.t + n.d);
      });
    } catch(e) {}
  }

  // Room Transition Function (Supports All 6 Zones & Elevator Sound)
  function switchRoom(targetZone, spawnX, spawnY) {
    if (state.transitioning) return;
    state.transitioning = true;

    if (state.activeDoor && (state.activeDoor.id.includes('lift') || state.activeDoor.sound === 'lift')) {
      playElevatorChime();
    } else {
      playDoorSound();
    }

    // Hide all prompts
    hideAllDoorPrompts();

    // Update State
    state.currentZone = targetZone;
    state.x = spawnX;
    state.y = spawnY;
    state.activeDoor = null;

    // Hide all room layers
    roomBedroomEl.style.display = 'none';
    roomBalconyEl.style.display = 'none';
    roomBathroomEl.style.display = 'none';
    roomLivingRoomEl.style.display = 'none';
    if (roomCorridorEl) roomCorridorEl.style.display = 'none';
    if (roomLobbyEl) roomLobbyEl.style.display = 'none';
    if (roomStreetEl) roomStreetEl.style.display = 'none';

    if (hudEl) hudEl.style.display = targetZone === 'street' ? 'none' : 'block';

    // Show targeted room layer only
    if (targetZone === 'bedroom') {
      roomBedroomEl.style.display = 'block';
      if (playerEl) playerEl.style.display = 'block';
      locationLabel.textContent = 'BEDROOM';
      locationLabel.setAttribute('fill', '#00ffff');
    } else if (targetZone === 'balcony') {
      roomBalconyEl.style.display = 'block';
      if (playerEl) playerEl.style.display = 'block';
      locationLabel.textContent = 'BALCONY (CITY VIEW)';
      locationLabel.setAttribute('fill', '#7dd3fc');
    } else if (targetZone === 'bathroom') {
      roomBathroomEl.style.display = 'block';
      if (playerEl) playerEl.style.display = 'block';
      locationLabel.textContent = 'BATHROOM (REMASTERED)';
      locationLabel.setAttribute('fill', '#38ef7d');
    } else if (targetZone === 'livingroom') {
      roomLivingRoomEl.style.display = 'block';
      if (playerEl) playerEl.style.display = 'block';
      locationLabel.textContent = 'LIVING ROOM';
      locationLabel.setAttribute('fill', '#ffd166');
    } else if (targetZone === 'corridor') {
      if (roomCorridorEl) roomCorridorEl.style.display = 'block';
      if (playerEl) playerEl.style.display = 'block';
      locationLabel.textContent = '4TH FLOOR CORRIDOR';
      locationLabel.setAttribute('fill', '#fb923c');
    } else if (targetZone === 'lobby') {
      if (roomLobbyEl) roomLobbyEl.style.display = 'block';
      if (playerEl) playerEl.style.display = 'block';
      updateCharacterFacing('up');
      locationLabel.textContent = 'GROUND LOBBY & RECEPTION';
      locationLabel.setAttribute('fill', '#c084fc');
    } else if (targetZone === 'street') {
      if (roomStreetEl) roomStreetEl.style.display = 'block';
      if (playerEl) playerEl.style.display = 'none';
      if (hudEl) hudEl.style.display = 'none';
      streetCam.x = 0;
      streetCam.z = 35;
      streetCam.theta = 0;
      streetCam.walkCycle = 0;
      locationLabel.textContent = 'TOKYO EXTERIOR (FIRST-PERSON)';
      locationLabel.setAttribute('fill', '#38bdf8');
      renderStreet3D();
    }

    state.keys.w = state.keys.a = state.keys.s = state.keys.d = false;
    state.keys.up = state.keys.left = state.keys.down = state.keys.right = false;

    playerEl.setAttribute('transform', `translate(${state.x}, ${state.y})`);

    setTimeout(() => {
      state.transitioning = false;
      updateProximity();
    }, 220);
  }

  function hideAllDoorPrompts() {
    if (promptBalconyDoor) promptBalconyDoor.style.display = 'none';
    if (promptBathroomDoor) promptBathroomDoor.style.display = 'none';
    if (promptLivingDoor) promptLivingDoor.style.display = 'none';
    if (promptBalconyExit) promptBalconyExit.style.display = 'none';
    if (promptBathroomExit) promptBathroomExit.style.display = 'none';
    if (promptLivingExit) promptLivingExit.style.display = 'none';
    if (promptLivingWorkstation) promptLivingWorkstation.style.display = 'none';
    if (promptLivingCorridor) promptLivingCorridor.style.display = 'none';
    if (promptCorridorLiving) promptCorridorLiving.style.display = 'none';
    if (promptCorridorLift) promptCorridorLift.style.display = 'none';
    if (promptCorridorStairs) promptCorridorStairs.style.display = 'none';
    if (promptLobbyLift) promptLobbyLift.style.display = 'none';
    if (promptLobbyStairs) promptLobbyStairs.style.display = 'none';
    if (promptLobbyStreet) promptLobbyStreet.style.display = 'none';
    if (promptStreetLobby) promptStreetLobby.style.display = 'none';
  }

  // Check Proximity for Doors (Requires [E] to enter)
  function updateDoorProximity() {
    if (state.transitioning) return;
    const currentData = ROOM_DATA[state.currentZone];
    if (!currentData || !currentData.doors) {
      state.activeDoor = null;
      hideAllDoorPrompts();
      return;
    }

    let foundDoor = null;

    for (let i = 0; i < currentData.doors.length; i++) {
      const door = currentData.doors[i];
      const dx = state.x - door.hotspot.x;
      const dy = state.y - door.hotspot.y;
      const dist = Math.sqrt(dx * dx + dy * dy);

      if (dist < door.hotspot.radius) {
        foundDoor = door;
        break;
      }
    }

    // Update active door & UI badge
    hideAllDoorPrompts();
    state.activeDoor = foundDoor;

    if (foundDoor && foundDoor.promptEl) {
      const pEl = promptMap[foundDoor.promptEl];
      if (pEl) pEl.style.display = 'block';
    }
  }

  // Check Proximity to Desk/Computer/Workstation
  function updateProximity() {
    if (state.currentZone === 'bedroom') {
      const hotspot = ROOM_DATA.bedroom.computerHotspot;
      const dx = state.x - hotspot.x;
      const dy = state.y - hotspot.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      state.isNearComputer = dist < hotspot.radius;

      if (state.isNearComputer && !state.modalOpen) {
        interactPrompt.style.display = 'block';
      } else {
        interactPrompt.style.display = 'none';
      }
      if (promptLivingWorkstation) promptLivingWorkstation.style.display = 'none';
    } else if (state.currentZone === 'livingroom') {
      interactPrompt.style.display = 'none';
      const hotspot = ROOM_DATA.livingroom.workstationHotspot;
      if (hotspot) {
        const dx = state.x - hotspot.x;
        const dy = state.y - hotspot.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        state.isNearComputer = dist < hotspot.radius;

        if (promptLivingWorkstation) {
          if (state.isNearComputer && !state.modalOpen) {
            promptLivingWorkstation.style.display = 'block';
          } else {
            promptLivingWorkstation.style.display = 'none';
          }
        }
      } else {
        state.isNearComputer = false;
        if (promptLivingWorkstation) promptLivingWorkstation.style.display = 'none';
      }
    } else {
      interactPrompt.style.display = 'none';
      if (promptLivingWorkstation) promptLivingWorkstation.style.display = 'none';
      state.isNearComputer = false;
    }

    updateDoorProximity();
  }

  // Open / Close Computer OS Modal
  function openComputerModal() {
    if (state.currentZone !== 'bedroom' && state.currentZone !== 'livingroom') return;
    state.modalOpen = true;
    interactPrompt.style.display = 'none';
    if (promptLivingWorkstation) promptLivingWorkstation.style.display = 'none';
    computerModal.style.display = 'block';
    playTone(600, 0.1);
  }

  function closeComputerModal() {
    state.modalOpen = false;
    closeXPShutdownDialog();
    if (xpStartMenu) xpStartMenu.style.display = 'none';
    state.startMenuOpen = false;
    computerModal.style.display = 'none';
    updateProximity();
    playTone(400, 0.08);
    if (svg) svg.focus();
  }

  // Windows XP Tab Switching
  function switchXPTab(tab) {
    state.xpTab = tab;
    const tabBgSpecs = document.getElementById('tab-bg-specs');
    const tabTxtSpecs = document.getElementById('tab-txt-specs');
    const tabBgNotepad = document.getElementById('tab-bg-notepad');
    const tabTxtNotepad = document.getElementById('tab-txt-notepad');
    const tabBgIE = document.getElementById('tab-bg-ie');
    const tabTxtIE = document.getElementById('tab-txt-ie');

    if (xpViewSpecs) xpViewSpecs.style.display = tab === 'specs' ? 'block' : 'none';
    if (xpViewNotepad) xpViewNotepad.style.display = tab === 'notepad' ? 'block' : 'none';
    if (xpViewIE) xpViewIE.style.display = tab === 'ie' ? 'block' : 'none';

    if (tabBgSpecs) tabBgSpecs.setAttribute('fill', tab === 'specs' ? '#ffffff' : '#ece9d8');
    if (tabTxtSpecs) {
      tabTxtSpecs.setAttribute('fill', tab === 'specs' ? '#0055ea' : '#334155');
      tabTxtSpecs.setAttribute('font-weight', tab === 'specs' ? 'bold' : 'normal');
    }

    if (tabBgNotepad) tabBgNotepad.setAttribute('fill', tab === 'notepad' ? '#ffffff' : '#ece9d8');
    if (tabTxtNotepad) {
      tabTxtNotepad.setAttribute('fill', tab === 'notepad' ? '#0055ea' : '#334155');
      tabTxtNotepad.setAttribute('font-weight', tab === 'notepad' ? 'bold' : 'normal');
    }

    if (tabBgIE) tabBgIE.setAttribute('fill', tab === 'ie' ? '#ffffff' : '#ece9d8');
    if (tabTxtIE) {
      tabTxtIE.setAttribute('fill', tab === 'ie' ? '#0055ea' : '#334155');
      tabTxtIE.setAttribute('font-weight', tab === 'ie' ? 'bold' : 'normal');
    }
    playTone(600, 0.05);
  }

  function toggleStartMenu() {
    if (!state.modalOpen || !state.computerPowered) return;
    state.startMenuOpen = !state.startMenuOpen;
    if (xpStartMenu) {
      xpStartMenu.style.display = state.startMenuOpen ? 'block' : 'none';
    }
    playTone(550, 0.06);
  }

  function openXPShutdownDialog() {
    if (xpStartMenu) {
      xpStartMenu.style.display = 'none';
      state.startMenuOpen = false;
    }
    if (xpShutdownDialog) {
      xpShutdownDialog.style.display = 'block';
      state.shutdownDialogOpen = true;
    }
    playTone(450, 0.08);
  }

  function closeXPShutdownDialog() {
    if (xpShutdownDialog) {
      xpShutdownDialog.style.display = 'none';
      state.shutdownDialogOpen = false;
    }
    playTone(400, 0.06);
  }

  function shutDownComputer() {
    closeXPShutdownDialog();
    if (xpStartMenu) {
      xpStartMenu.style.display = 'none';
      state.startMenuOpen = false;
    }
    playXPShutdownChime();
    state.computerPowered = false;

    if (screenDisplay) screenDisplay.setAttribute('stroke', '#333b4d');
    if (screenContent) screenContent.style.display = 'none';
    if (screenOffContent) screenOffContent.style.display = 'block';
    if (screenGlow) screenGlow.style.display = 'none';
    if (monitorLed) monitorLed.setAttribute('fill', '#333b4d');
    if (powerLed) powerLed.setAttribute('fill', '#484f58');
    if (powerLedGlow) powerLedGlow.style.display = 'none';
    if (monitorPowerLed) monitorPowerLed.setAttribute('fill', '#f59e0b');

    if (modalOnlineView) modalOnlineView.style.display = 'none';
    if (modalOfflineView) modalOfflineView.style.display = 'block';
  }

  function powerOnComputer() {
    playXPStartupChime();
    state.computerPowered = true;

    if (screenDisplay) screenDisplay.setAttribute('stroke', '#00ffff');
    if (screenContent) screenContent.style.display = 'block';
    if (screenOffContent) screenOffContent.style.display = 'none';
    if (screenGlow) screenGlow.style.display = 'block';
    if (monitorLed) monitorLed.setAttribute('fill', '#00ffff');
    if (powerLed) powerLed.setAttribute('fill', '#00ffff');
    if (powerLedGlow) powerLedGlow.style.display = 'block';
    if (monitorPowerLed) monitorPowerLed.setAttribute('fill', '#22c55e');

    if (modalOnlineView) modalOnlineView.style.display = 'block';
    if (modalOfflineView) modalOfflineView.style.display = 'none';
    switchXPTab('specs');
  }

  // Windows XP Interactive Desktop Listeners
  if (tabBtnSpecs) tabBtnSpecs.addEventListener('click', () => switchXPTab('specs'));
  if (tabBtnNotepad) tabBtnNotepad.addEventListener('click', () => switchXPTab('notepad'));
  if (tabBtnIE) tabBtnIE.addEventListener('click', () => switchXPTab('ie'));
  if (linkShowSpecs) linkShowSpecs.addEventListener('click', () => switchXPTab('specs'));
  if (linkShowNotepad) linkShowNotepad.addEventListener('click', () => switchXPTab('notepad'));
  if (btnXPOpenMemo) btnXPOpenMemo.addEventListener('click', () => switchXPTab('notepad'));
  if (btnXPOpenWeb) btnXPOpenWeb.addEventListener('click', () => switchXPTab('ie'));
  if (menuItemIE) menuItemIE.addEventListener('click', () => { toggleStartMenu(); switchXPTab('ie'); });
  if (menuItemNotepad) menuItemNotepad.addEventListener('click', () => { toggleStartMenu(); switchXPTab('notepad'); });

  if (iconMyComp) iconMyComp.addEventListener('click', () => switchXPTab('specs'));
  if (iconMyDocs) iconMyDocs.addEventListener('click', () => switchXPTab('notepad'));
  if (iconIE) iconIE.addEventListener('click', () => switchXPTab('ie'));
  if (iconPortfolio) iconPortfolio.addEventListener('click', () => switchXPTab('ie'));
  if (iconNotepad) iconNotepad.addEventListener('click', () => switchXPTab('notepad'));
  if (iconRecycle) iconRecycle.addEventListener('click', () => playTone(300, 0.08, 'sawtooth'));

  if (xpStartBtn) xpStartBtn.addEventListener('click', toggleStartMenu);
  if (xpMenuShutdown) xpMenuShutdown.addEventListener('click', openXPShutdownDialog);
  if (linkShutdown) linkShutdown.addEventListener('click', openXPShutdownDialog);
  if (btnShutdownFromSpecs) btnShutdownFromSpecs.addEventListener('click', openXPShutdownDialog);
  if (xpConfirmShutdown) xpConfirmShutdown.addEventListener('click', shutDownComputer);
  if (xpCancelShutdown) xpCancelShutdown.addEventListener('click', closeXPShutdownDialog);
  if (xpCloseWindow) xpCloseWindow.addEventListener('click', closeComputerModal);
  if (btnMonitorPower) btnMonitorPower.addEventListener('click', () => {
    if (state.computerPowered) shutDownComputer(); else powerOnComputer();
  });

  // Door Clicks: ONLY triggered if player is already near the door!
  function handleDoorClick(doorId) {
    if (state.activeDoor && state.activeDoor.id === doorId && !state.modalOpen) {
      switchRoom(state.activeDoor.targetZone, state.activeDoor.spawnX, state.activeDoor.spawnY);
    }
  }

  if (doorToBalcony) doorToBalcony.addEventListener('click', () => handleDoorClick('balcony-door'));
  if (doorToBathroom) doorToBathroom.addEventListener('click', () => handleDoorClick('bathroom-door'));
  if (doorToLiving) doorToLiving.addEventListener('click', () => handleDoorClick('livingroom-door'));
  if (exitBalcony) exitBalcony.addEventListener('click', () => handleDoorClick('balcony-exit'));
  if (exitBathroom) exitBathroom.addEventListener('click', () => handleDoorClick('bathroom-exit'));
  if (exitLiving) exitLiving.addEventListener('click', () => handleDoorClick('livingroom-exit'));
  if (doorToCorridor) doorToCorridor.addEventListener('click', () => handleDoorClick('living-to-corridor'));
  if (exitCorridorToLiving) exitCorridorToLiving.addEventListener('click', () => handleDoorClick('corridor-to-living'));
  if (doorCorridorToLift) doorCorridorToLift.addEventListener('click', () => handleDoorClick('corridor-to-lift'));
  if (doorCorridorToStairs) doorCorridorToStairs.addEventListener('click', () => handleDoorClick('corridor-to-stairs'));
  if (doorLobbyToLift) doorLobbyToLift.addEventListener('click', () => handleDoorClick('lobby-to-lift'));
  if (doorLobbyToStairs) doorLobbyToStairs.addEventListener('click', () => handleDoorClick('lobby-to-stairs'));
  if (doorLobbyToStreet) doorLobbyToStreet.addEventListener('click', () => handleDoorClick('lobby-to-street'));
  if (promptLobbyStreet) promptLobbyStreet.addEventListener('click', () => handleDoorClick('lobby-to-street'));
  if (promptStreetLobby) {
    promptStreetLobby.addEventListener('click', (e) => {
      if (state.currentZone === 'street') {
        e.stopPropagation();
        switchRoom('lobby', 480, 480);
      }
    });
  }
  if (streetHudEl) {
    streetHudEl.addEventListener('click', (e) => {
      if (state.currentZone === 'street') {
        const nearEntrance = (Math.abs(streetCam.x) <= 85 && streetCam.z <= 95) ||
                             (promptStreetLobby && promptStreetLobby.style.display === 'block') ||
                             (state.activeDoor && state.activeDoor.id === 'street-to-lobby');
        if (nearEntrance) {
          e.stopPropagation();
          switchRoom('lobby', 480, 480);
        }
      }
    });
  }

  if (promptBalconyDoor) promptBalconyDoor.addEventListener('click', () => handleDoorClick('balcony-door'));
  if (promptBathroomDoor) promptBathroomDoor.addEventListener('click', () => handleDoorClick('bathroom-door'));
  if (promptLivingDoor) promptLivingDoor.addEventListener('click', () => handleDoorClick('livingroom-door'));
  if (promptBalconyExit) promptBalconyExit.addEventListener('click', () => handleDoorClick('balcony-exit'));
  if (promptBathroomExit) promptBathroomExit.addEventListener('click', () => handleDoorClick('bathroom-exit'));
  if (promptLivingExit) promptLivingExit.addEventListener('click', () => handleDoorClick('livingroom-exit'));
  if (promptLivingCorridor) promptLivingCorridor.addEventListener('click', () => handleDoorClick('living-to-corridor'));
  if (promptCorridorLiving) promptCorridorLiving.addEventListener('click', () => handleDoorClick('corridor-to-living'));
  if (promptCorridorLift) promptCorridorLift.addEventListener('click', () => handleDoorClick('corridor-to-lift'));
  if (promptCorridorStairs) promptCorridorStairs.addEventListener('click', () => handleDoorClick('corridor-to-stairs'));
  if (promptLobbyLift) promptLobbyLift.addEventListener('click', () => handleDoorClick('lobby-to-lift'));
  if (promptLobbyStairs) promptLobbyStairs.addEventListener('click', () => handleDoorClick('lobby-to-stairs'));

  if (promptLivingWorkstation) {
    promptLivingWorkstation.addEventListener('click', function () {
      if (state.isNearComputer && !state.modalOpen) {
        openComputerModal();
      }
    });
  }
  if (livingWorkstationEl) {
    livingWorkstationEl.addEventListener('click', function () {
      if (state.isNearComputer && !state.modalOpen) {
        openComputerModal();
      }
    });
  }

  if (btnCloseModal) btnCloseModal.addEventListener('click', closeComputerModal);
  if (btnCloseDot) btnCloseDot.addEventListener('click', closeComputerModal);
  if (modalBackdrop) modalBackdrop.addEventListener('click', closeComputerModal);
  if (btnShutdown) btnShutdown.addEventListener('click', shutDownComputer);
  if (btnPowerOn) btnPowerOn.addEventListener('click', powerOnComputer);

  // Collision Detection per active room (Supports 2.5D Foot-Anchored Physics)
  function checkCollision(nx, ny) {
    const currentData = ROOM_DATA[state.currentZone];
    if (!currentData) return false;

    if (currentData.footCollision) {
      const footLeft = nx - 12;
      const footRight = nx + 12;
      const footTop = ny + 26;
      const footBottom = ny + 38;

      if (footLeft < currentData.bounds.minX || footRight > currentData.bounds.maxX) return true;
      if (footTop < currentData.bounds.minY || footBottom > currentData.bounds.maxY) return true;

      for (let i = 0; i < currentData.obstacles.length; i++) {
        const obs = currentData.obstacles[i];
        if (
          footRight > obs.x &&
          footLeft < obs.x + obs.w &&
          footBottom > obs.y &&
          footTop < obs.y + obs.h
        ) {
          return true;
        }
      }
      return false;
    } else {
      const charRadius = 15;
      if (nx - charRadius < currentData.bounds.minX || nx + charRadius > currentData.bounds.maxX) return true;
      if (ny - 5 < currentData.bounds.minY || ny + 20 > currentData.bounds.maxY) return true;

      for (let i = 0; i < currentData.obstacles.length; i++) {
        const obs = currentData.obstacles[i];
        if (
          nx + charRadius > obs.x &&
          nx - charRadius < obs.x + obs.w &&
          ny + 15 > obs.y &&
          ny - 10 < obs.y + obs.h
        ) {
          return true;
        }
      }
      return false;
    }
  }

  // Input Event Listeners
  function handleKeyDown(e) {
    if (e.key === 'Escape') {
      if (state.modalOpen) {
        closeComputerModal();
        return;
      }
    }

    const key = e.key ? e.key.toLowerCase() : '';

    // [E] KEY ACTION: Check Door Transition FIRST or Computer Interaction
    if (key === 'e' || key === ' ' || key === 'enter' || e.code === 'KeyE' || e.code === 'Space' || e.code === 'Enter') {
      // 1. Street Mode: Check if near apartment entrance!
      if (state.currentZone === 'street' && !state.modalOpen) {
        const nearEntrance = (Math.abs(streetCam.x) <= 85 && streetCam.z <= 95) ||
                             (promptStreetLobby && promptStreetLobby.style.display === 'block') ||
                             (state.activeDoor && state.activeDoor.id === 'street-to-lobby');
        if (nearEntrance) {
          e.preventDefault();
          switchRoom('lobby', 480, 480);
          return;
        }
      }

      // 2. Door Transition in 2D rooms (only when near!)
      if (state.activeDoor && !state.modalOpen) {
        e.preventDefault();
        switchRoom(state.activeDoor.targetZone, state.activeDoor.spawnX, state.activeDoor.spawnY);
        return;
      }

      // 3. Computer Interaction (only when near in bedroom!)
      if (state.isNearComputer && !state.modalOpen) {
        e.preventDefault();
        openComputerModal();
        return;
      }
    }

    if (state.modalOpen) return;

    if (key === 'w' || e.code === 'KeyW') { state.keys.w = true; e.preventDefault(); }
    if (key === 's' || e.code === 'KeyS') { state.keys.s = true; e.preventDefault(); }
    if (key === 'a' || e.code === 'KeyA') { state.keys.a = true; e.preventDefault(); }
    if (key === 'd' || e.code === 'KeyD') { state.keys.d = true; e.preventDefault(); }
    if (key === 'arrowup' || e.code === 'ArrowUp') { state.keys.up = true; e.preventDefault(); }
    if (key === 'arrowdown' || e.code === 'ArrowDown') { state.keys.down = true; e.preventDefault(); }
    if (key === 'arrowleft' || e.code === 'ArrowLeft') { state.keys.left = true; e.preventDefault(); }
    if (key === 'arrowright' || e.code === 'ArrowRight') { state.keys.right = true; e.preventDefault(); }
  }

  function handleKeyUp(e) {
    const key = e.key ? e.key.toLowerCase() : '';
    if (key === 'w' || e.code === 'KeyW') state.keys.w = false;
    if (key === 's' || e.code === 'KeyS') state.keys.s = false;
    if (key === 'a' || e.code === 'KeyA') state.keys.a = false;
    if (key === 'd' || e.code === 'KeyD') state.keys.d = false;
    if (key === 'arrowup' || e.code === 'ArrowUp') state.keys.up = false;
    if (key === 'arrowdown' || e.code === 'ArrowDown') state.keys.down = false;
    if (key === 'arrowleft' || e.code === 'ArrowLeft') state.keys.left = false;
    if (key === 'arrowright' || e.code === 'ArrowRight') state.keys.right = false;
  }

  // Click Listeners (Strictly Require Proximity!)
  if (interactPrompt) interactPrompt.addEventListener('click', openComputerModal);
  if (computerStation) {
    computerStation.addEventListener('click', function () {
      if (state.isNearComputer && !state.modalOpen) {
        openComputerModal();
      }
    });
  }

  // Door Clicks: ONLY triggered if player is already near the door!
  function handleDoorClick(doorId) {
    if (state.activeDoor && state.activeDoor.id === doorId && !state.modalOpen) {
      switchRoom(state.activeDoor.targetZone, state.activeDoor.spawnX, state.activeDoor.spawnY);
    }
  }

  if (doorToBalcony) doorToBalcony.addEventListener('click', () => handleDoorClick('balcony-door'));
  if (doorToBathroom) doorToBathroom.addEventListener('click', () => handleDoorClick('bathroom-door'));
  if (doorToLiving) doorToLiving.addEventListener('click', () => handleDoorClick('livingroom-door'));
  if (exitBalcony) exitBalcony.addEventListener('click', () => handleDoorClick('balcony-exit'));
  if (exitBathroom) exitBathroom.addEventListener('click', () => handleDoorClick('bathroom-exit'));
  if (exitLiving) exitLiving.addEventListener('click', () => handleDoorClick('livingroom-exit'));

  if (promptBalconyDoor) promptBalconyDoor.addEventListener('click', () => handleDoorClick('balcony-door'));
  if (promptBathroomDoor) promptBathroomDoor.addEventListener('click', () => handleDoorClick('bathroom-door'));
  if (promptLivingDoor) promptLivingDoor.addEventListener('click', () => handleDoorClick('livingroom-door'));
  if (promptBalconyExit) promptBalconyExit.addEventListener('click', () => handleDoorClick('balcony-exit'));
  if (promptBathroomExit) promptBathroomExit.addEventListener('click', () => handleDoorClick('bathroom-exit'));
  if (promptLivingExit) promptLivingExit.addEventListener('click', () => handleDoorClick('livingroom-exit'));
  if (promptLivingWorkstation) {
    promptLivingWorkstation.addEventListener('click', function () {
      if (state.isNearComputer && !state.modalOpen) {
        openComputerModal();
      }
    });
  }
  if (livingWorkstationEl) {
    livingWorkstationEl.addEventListener('click', function () {
      if (state.isNearComputer && !state.modalOpen) {
        openComputerModal();
      }
    });
  }

  if (btnCloseModal) btnCloseModal.addEventListener('click', closeComputerModal);
  if (btnCloseDot) btnCloseDot.addEventListener('click', closeComputerModal);
  if (modalBackdrop) modalBackdrop.addEventListener('click', closeComputerModal);
  if (btnShutdown) btnShutdown.addEventListener('click', shutDownComputer);
  if (btnPowerOn) btnPowerOn.addEventListener('click', powerOnComputer);

  window.addEventListener('keydown', handleKeyDown);
  window.addEventListener('keyup', handleKeyUp);
  svg.addEventListener('click', function () { svg.focus(); });
  svg.focus();

  function updateCharacterFacing(facing) {
    if (facing === 'up') {
      if (spriteFrontBackEl) spriteFrontBackEl.style.display = 'block';
      if (spriteRightEl) spriteRightEl.style.display = 'none';
      if (spriteLeftEl) spriteLeftEl.style.display = 'none';

      eyesEl.style.display = 'none';
      shirtCollarEl.style.display = 'none';
      tieEl.style.display = 'none';
      lapelLEl.style.display = 'none';
      lapelREl.style.display = 'none';
      suitBtn1El.style.display = 'none';
      suitBtn2El.style.display = 'none';
      if (frontHairEl) frontHairEl.style.display = 'none';
      if (sweaterVestGroupEl) sweaterVestGroupEl.style.display = 'none';
      if (faceGroupEl) faceGroupEl.style.display = 'none';
    } else if (facing === 'down') {
      if (spriteFrontBackEl) spriteFrontBackEl.style.display = 'block';
      if (spriteRightEl) spriteRightEl.style.display = 'none';
      if (spriteLeftEl) spriteLeftEl.style.display = 'none';

      eyesEl.style.display = 'block';
      shirtCollarEl.style.display = 'block';
      tieEl.style.display = 'block';
      lapelLEl.style.display = 'block';
      lapelREl.style.display = 'block';
      suitBtn1El.style.display = 'block';
      suitBtn2El.style.display = 'block';
      if (frontHairEl) frontHairEl.style.display = 'block';
      if (sweaterVestGroupEl) sweaterVestGroupEl.style.display = 'block';
      if (faceGroupEl) faceGroupEl.style.display = 'block';
    } else if (facing === 'right') {
      if (spriteFrontBackEl) spriteFrontBackEl.style.display = 'none';
      if (spriteRightEl) spriteRightEl.style.display = 'block';
      if (spriteLeftEl) spriteLeftEl.style.display = 'none';
    } else if (facing === 'left') {
      if (spriteFrontBackEl) spriteFrontBackEl.style.display = 'none';
      if (spriteRightEl) spriteRightEl.style.display = 'none';
      if (spriteLeftEl) spriteLeftEl.style.display = 'block';
    }
  }


  // =========================================================================
  // =========================================================================
  // PSEUDO-3D FIRST-PERSON TOKYO NEIGHBOURHOOD ENGINE
  // =========================================================================
  const streetCam = {
    x: 0,
    z: 35,
    theta: 0, // 0 = facing North (+Z), PI/2 = facing East (+X), PI = South (-Z), -PI/2 = West (-X)
    speed: 3.8,
    turnSpeed: 0.048,
    walkCycle: 0,
    vx: 480,
    vy: 310,
    f: 320
  };

  function toCamSpace(x, y, z) {
    const dx = x - streetCam.x;
    const dz = z - streetCam.z;
    const c = Math.cos(streetCam.theta);
    const s = Math.sin(streetCam.theta);
    return {
      x: dx * c - dz * s,
      y: y + Math.sin(streetCam.walkCycle) * 2.2,
      z: dx * s + dz * c
    };
  }

  function clipPolyNear(poly, zNear = 12) {
    if (poly.length < 3) return [];
    const out = [];
    const n = poly.length;
    for (let i = 0; i < n; i++) {
      const cur = poly[i];
      const prev = poly[(i + n - 1) % n];
      const curIn = cur.z >= zNear;
      const prevIn = prev.z >= zNear;
      if (curIn) {
        if (!prevIn) {
          const t = (zNear - prev.z) / (cur.z - prev.z);
          out.push({
            x: prev.x + t * (cur.x - prev.x),
            y: prev.y + t * (cur.y - prev.y),
            z: zNear
          });
        }
        out.push(cur);
      } else if (prevIn) {
        const t = (zNear - prev.z) / (cur.z - prev.z);
        out.push({
          x: prev.x + t * (cur.x - prev.x),
          y: prev.y + t * (cur.y - prev.y),
          z: zNear
        });
      }
    }
    return out;
  }

  function projectRel(p) {
    const scale = streetCam.f / p.z;
    return {
      x: streetCam.vx + p.x * scale,
      y: streetCam.vy + p.y * scale,
      scale: scale,
      z: p.z
    };
  }

  const streetBuildings = [
    {
      id: 'b-cafe-apts',
      x1: -340, x2: -85,
      z1: 60, z2: 290,
      yTop: -320, yBot: 112,
      wallCol: '#151d2c', sideCol: '#0c111a', roofCol: '#080c14',
      type: 'cafe-apts'
    },
    {
      id: 'b-izakaya-ramen',
      x1: 85, x2: 340,
      z1: 60, z2: 290,
      yTop: -240, yBot: 112,
      wallCol: '#1f1616', sideCol: '#110d0d', roofCol: '#090707',
      type: 'izakaya'
    },
    {
      id: 'b-konbini-lawson',
      x1: 85, x2: 340,
      z1: 420, z2: 620,
      yTop: -270, yBot: 112,
      wallCol: '#151f30', sideCol: '#0d131f', roofCol: '#080c14',
      type: 'konbini'
    },
    {
      id: 'b-mansion-north-w',
      x1: -340, x2: -85,
      z1: 750, z2: 850,
      yTop: -360, yBot: 112,
      wallCol: '#131826', sideCol: '#0b0e18', roofCol: '#070910',
      type: 'mansion'
    },
    {
      id: 'b-office-north-e',
      x1: 85, x2: 340,
      z1: 750, z2: 850,
      yTop: -330, yBot: 112,
      wallCol: '#161b28', sideCol: '#0c0f18', roofCol: '#080b12',
      type: 'office'
    }
  ];

  function isStreetObstacle(x, z) {
    const margin = 16;
    for (let i = 0; i < streetBuildings.length; i++) {
      const b = streetBuildings[i];
      if (x >= b.x1 - margin && x <= b.x2 + margin &&
          z >= b.z1 - margin && z <= b.z2 + margin) {
        return true;
      }
    }
    // Tokyo Pocket Park perimeter curb (opening at South Z=420 X=-230..-190, and East X=-85 Z=500..540)
    if (x >= -340 - margin && x <= -85 + margin && z >= 420 - margin && z <= 620 + margin) {
      const onBorder = (x <= -335 || x >= -90 || z <= 425 || z >= 615);
      const isGate = (x >= -230 && x <= -190 && z <= 425) || (x >= -92 && z >= 500 && z <= 540);
      if (onBorder && !isGate) return true;
    }
    return false;
  }

  function renderStreet3D() {
    if (!streetDynamicEl) return;
    const renderList = [];

    function addPoly(verts, fill, stroke = 'none', strokeW = 0, extra = '') {
      const camVerts = verts.map(v => toCamSpace(v.x, v.y, v.z));
      const clipped = clipPolyNear(camVerts, 12);
      if (clipped.length < 3) return;

      let avgZ = 0;
      let minX = 9999, maxX = -9999, minY = 9999, maxY = -9999;
      const pts2d = [];

      for (let i = 0; i < clipped.length; i++) {
        const p = projectRel(clipped[i]);
        pts2d.push(p.x.toFixed(1) + ',' + p.y.toFixed(1));
        avgZ += clipped[i].z;
        if (p.x < minX) minX = p.x;
        if (p.x > maxX) maxX = p.x;
        if (p.y < minY) minY = p.y;
        if (p.y > maxY) maxY = p.y;
      }
      avgZ /= clipped.length;

      if (maxX < -80 || minX > 1040 || maxY < -80 || minY > 720) return;

      const strokeAttr = stroke !== 'none' ? `stroke="${stroke}" stroke-width="${strokeW}"` : '';
      const svg = `<polygon points="${pts2d.join(' ')}" fill="${fill}" ${strokeAttr} ${extra} />`;
      renderList.push({ depth: avgZ, svg: svg });
    }

    // --- 1. ROADS AND INTERSECTIONS ---
    // Main Avenue
    addPoly([
      { x: -60, y: 112, z: 0 }, { x: 60, y: 112, z: 0 },
      { x: 60, y: 112, z: 850 }, { x: -60, y: 112, z: 850 }
    ], '#0d121c', '#1e293b', 0.5);

    // South Cross Street
    addPoly([
      { x: -420, y: 112, z: 310 }, { x: 420, y: 112, z: 310 },
      { x: 420, y: 112, z: 400 }, { x: -420, y: 112, z: 400 }
    ], '#0d121c', '#1e293b', 0.5);

    // North Cross Street
    addPoly([
      { x: -420, y: 112, z: 640 }, { x: 420, y: 112, z: 640 },
      { x: 420, y: 112, z: 730 }, { x: -420, y: 112, z: 730 }
    ], '#0d121c', '#1e293b', 0.5);

    // Connecting Lanes
    addPoly([
      { x: -420, y: 112, z: 310 }, { x: -340, y: 112, z: 310 },
      { x: -340, y: 112, z: 730 }, { x: -420, y: 112, z: 730 }
    ], '#0b0f17');

    addPoly([
      { x: 340, y: 112, z: 310 }, { x: 420, y: 112, z: 310 },
      { x: 420, y: 112, z: 730 }, { x: 340, y: 112, z: 730 }
    ], '#0b0f17');

    // Sidewalks with Curbs
    addPoly([
      { x: -85, y: 110, z: 0 }, { x: -60, y: 110, z: 0 },
      { x: -60, y: 110, z: 310 }, { x: -85, y: 110, z: 310 }
    ], '#19202e', '#334155', 0.5);
    addPoly([
      { x: -85, y: 110, z: 400 }, { x: -60, y: 110, z: 400 },
      { x: -60, y: 110, z: 640 }, { x: -85, y: 110, z: 640 }
    ], '#19202e', '#334155', 0.5);

    addPoly([
      { x: 60, y: 110, z: 0 }, { x: 85, y: 110, z: 0 },
      { x: 85, y: 110, z: 310 }, { x: 60, y: 110, z: 310 }
    ], '#19202e', '#334155', 0.5);
    addPoly([
      { x: 60, y: 110, z: 400 }, { x: 85, y: 110, z: 400 },
      { x: 85, y: 110, z: 640 }, { x: 60, y: 110, z: 640 }
    ], '#19202e', '#334155', 0.5);

    // Zebra Crossings at South Intersection
    for (let x = -52; x <= 46; x += 14) {
      addPoly([
        { x: x, y: 111.8, z: 295 }, { x: x + 8, y: 111.8, z: 295 },
        { x: x + 8, y: 111.8, z: 308 }, { x: x, y: 111.8, z: 308 }
      ], '#f1f5f9', 'none', 0, 'opacity="0.88"');
    }
    for (let x = -52; x <= 46; x += 14) {
      addPoly([
        { x: x, y: 111.8, z: 402 }, { x: x + 8, y: 111.8, z: 402 },
        { x: x + 8, y: 111.8, z: 415 }, { x: x, y: 111.8, z: 415 }
      ], '#f1f5f9', 'none', 0, 'opacity="0.88"');
    }

    // Centerline Dashes
    for (let z = 5; z < 840; z += 55) {
      if ((z >= 305 && z <= 405) || (z >= 635 && z <= 735)) continue;
      addPoly([
        { x: -1.5, y: 111.8, z: z }, { x: 1.5, y: 111.8, z: z },
        { x: 1.5, y: 111.8, z: z + 28 }, { x: -1.5, y: 111.8, z: z + 28 }
      ], '#f8fafc', 'none', 0, 'opacity="0.9"');
    }

    // --- 2. 3D VOLUMETRIC BUILDINGS ---
    for (let i = 0; i < streetBuildings.length; i++) {
      const b = streetBuildings[i];

      // South Face
      if (streetCam.z < b.z1) {
        addPoly([
          { x: b.x1, y: b.yBot, z: b.z1 }, { x: b.x2, y: b.yBot, z: b.z1 },
          { x: b.x2, y: b.yTop, z: b.z1 }, { x: b.x1, y: b.yTop, z: b.z1 }
        ], b.sideCol, '#070a10', 0.8);

        // Roof Cornice
        addPoly([
          { x: b.x1 - 4, y: b.yTop + 8, z: b.z1 - 3 }, { x: b.x2 + 4, y: b.yTop + 8, z: b.z1 - 3 },
          { x: b.x2 + 4, y: b.yTop, z: b.z1 - 3 }, { x: b.x1 - 4, y: b.yTop, z: b.z1 - 3 }
        ], '#2d3748');

        // Windows on South face
        [-80, -160, -240].forEach(wy => {
          if (wy > b.yTop + 40) {
            for (let wx = b.x1 + 30; wx <= b.x2 - 20; wx += 45) {
              const lit = ((wx * 3 + wy) % 5) !== 0;
              addPoly([
                { x: wx - 10, y: wy + 16, z: b.z1 - 0.5 }, { x: wx + 10, y: wy + 16, z: b.z1 - 0.5 },
                { x: wx + 10, y: wy - 16, z: b.z1 - 0.5 }, { x: wx - 10, y: wy - 16, z: b.z1 - 0.5 }
              ], lit ? '#fed7aa' : '#080c14', '#1e293b', 0.5, `opacity="${lit ? 0.75 : 0.4}"`);
            }
          }
        });
      }

      // North Face
      if (streetCam.z > b.z2) {
        addPoly([
          { x: b.x2, y: b.yBot, z: b.z2 }, { x: b.x1, y: b.yBot, z: b.z2 },
          { x: b.x1, y: b.yTop, z: b.z2 }, { x: b.x2, y: b.yTop, z: b.z2 }
        ], b.sideCol, '#070a10', 0.8);

        addPoly([
          { x: b.x2 + 4, y: b.yTop + 8, z: b.z2 + 3 }, { x: b.x1 - 4, y: b.yTop + 8, z: b.z2 + 3 },
          { x: b.x1 - 4, y: b.yTop, z: b.z2 + 3 }, { x: b.x2 + 4, y: b.yTop, z: b.z2 + 3 }
        ], '#2d3748');
      }

      // West Face
      if (streetCam.x < b.x1) {
        const col = b.x1 > 0 ? b.wallCol : b.sideCol;
        addPoly([
          { x: b.x1, y: b.yBot, z: b.z2 }, { x: b.x1, y: b.yBot, z: b.z1 },
          { x: b.x1, y: b.yTop, z: b.z1 }, { x: b.x1, y: b.yTop, z: b.z2 }
        ], col, '#070a10', 0.8);

        if (b.type === 'izakaya' && b.x1 > 0) {
          // Tiled Eave
          addPoly([
            { x: b.x1 - 18, y: 20, z: b.z2 - 10 }, { x: b.x1 - 18, y: 20, z: b.z1 + 10 },
            { x: b.x1, y: 0, z: b.z1 + 10 }, { x: b.x1, y: 0, z: b.z2 - 10 }
          ], '#1e293b', '#0f172a', 1);

          // Noren Curtain
          addPoly([
            { x: b.x1 - 1, y: 65, z: b.z1 + 95 }, { x: b.x1 - 1, y: 65, z: b.z1 + 45 },
            { x: b.x1 - 1, y: 25, z: b.z1 + 45 }, { x: b.x1 - 1, y: 25, z: b.z1 + 95 }
          ], '#b91c1c', '#7f1d1d', 0.8);

          // Red Lanterns
          [b.z1 + 35, b.z1 + 70, b.z1 + 105, b.z1 + 140].forEach(lz => {
            addPoly([
              { x: b.x1 - 12, y: 46, z: lz - 4 }, { x: b.x1 - 12, y: 46, z: lz + 4 },
              { x: b.x1 - 12, y: 28, z: lz + 4 }, { x: b.x1 - 12, y: 28, z: lz - 4 }
            ], '#dc2626', '#ef4444', 0.8, 'filter="url(#glow-pink)"');
          });
        } else if (b.type === 'konbini' && b.x1 > 0) {
          // Fascia Canopy Band
          addPoly([
            { x: b.x1 - 14, y: 22, z: b.z2 - 15 }, { x: b.x1 - 14, y: 22, z: b.z1 + 15 },
            { x: b.x1 - 14, y: -2, z: b.z1 + 15 }, { x: b.x1 - 14, y: -2, z: b.z2 - 15 }
          ], '#ffffff', '#0284c7', 1.2, 'filter="url(#glow-cyan)"');

          addPoly([
            { x: b.x1 - 14.5, y: 8, z: b.z2 - 16 }, { x: b.x1 - 14.5, y: 8, z: b.z1 + 16 },
            { x: b.x1 - 14.5, y: 2, z: b.z1 + 16 }, { x: b.x1 - 14.5, y: 2, z: b.z2 - 16 }
          ], '#0284c7');

          addPoly([
            { x: b.x1 - 0.5, y: 105, z: b.z2 - 25 }, { x: b.x1 - 0.5, y: 105, z: b.z1 + 25 },
            { x: b.x1 - 0.5, y: 26, z: b.z1 + 25 }, { x: b.x1 - 0.5, y: 26, z: b.z2 - 25 }
          ], '#fef08a', '#38bdf8', 1, 'opacity="0.38"');
        }
      }

      // East Face
      if (streetCam.x > b.x2) {
        const col = b.x2 < 0 ? b.wallCol : b.sideCol;
        addPoly([
          { x: b.x2, y: b.yBot, z: b.z1 }, { x: b.x2, y: b.yBot, z: b.z2 },
          { x: b.x2, y: b.yTop, z: b.z2 }, { x: b.x2, y: b.yTop, z: b.z1 }
        ], col, '#070a10', 0.8);

        if (b.type === 'cafe-apts' && b.x2 < 0) {
          // Awning
          addPoly([
            { x: b.x2 + 16, y: 35, z: b.z1 + 20 }, { x: b.x2 + 16, y: 35, z: b.z1 + 130 },
            { x: b.x2, y: 12, z: b.z1 + 130 }, { x: b.x2, y: 12, z: b.z1 + 20 }
          ], '#064e3b', '#047857', 1);

          addPoly([
            { x: b.x2 + 0.5, y: 105, z: b.z1 + 25 }, { x: b.x2 + 0.5, y: 105, z: b.z1 + 125 },
            { x: b.x2 + 0.5, y: 40, z: b.z1 + 125 }, { x: b.x2 + 0.5, y: 40, z: b.z1 + 25 }
          ], '#fed7aa', '#78350f', 0.8, 'opacity="0.45"');

          // Balconies and Windows
          [-70, -150, -230].forEach(by => {
            if (by > b.yTop + 30) {
              addPoly([
                { x: b.x2 + 14, y: by + 28, z: b.z1 + 30 }, { x: b.x2 + 14, y: by + 28, z: b.z2 - 30 },
                { x: b.x2, y: by + 28, z: b.z2 - 30 }, { x: b.x2, y: by + 28, z: b.z1 + 30 }
              ], '#1e293b');

              addPoly([
                { x: b.x2 + 14, y: by + 28, z: b.z1 + 30 }, { x: b.x2 + 14, y: by + 28, z: b.z2 - 30 },
                { x: b.x2 + 14, y: by + 4, z: b.z2 - 30 }, { x: b.x2 + 14, y: by + 4, z: b.z1 + 30 }
              ], '#334155', '#475569', 0.8, 'opacity="0.6"');

              for (let wz = b.z1 + 45; wz < b.z2 - 35; wz += 45) {
                const lit = ((wz * 7 + by) % 3) !== 0;
                addPoly([
                  { x: b.x2 + 0.5, y: by + 18, z: wz - 12 }, { x: b.x2 + 0.5, y: by + 18, z: wz + 12 },
                  { x: b.x2 + 0.5, y: by - 14, z: wz + 12 }, { x: b.x2 + 0.5, y: by - 14, z: wz - 12 }
                ], lit ? '#fed7aa' : '#0a0e17', '#334155', 0.5, `opacity="${lit ? 0.75 : 0.4}"`);

                if (wz % 2 === 0) {
                  addPoly([
                    { x: b.x2 + 6, y: by + 28, z: wz - 8 }, { x: b.x2 + 6, y: by + 28, z: wz + 8 },
                    { x: b.x2 + 6, y: by + 18, z: wz + 8 }, { x: b.x2 + 6, y: by + 18, z: wz - 8 }
                  ], '#94a3b8', '#475569', 0.5);
                }
              }
            }
          });
        }
      }

      // Roof Cap
      addPoly([
        { x: b.x1, y: b.yTop, z: b.z1 }, { x: b.x2, y: b.yTop, z: b.z1 },
        { x: b.x2, y: b.yTop, z: b.z2 }, { x: b.x1, y: b.yTop, z: b.z2 }
      ], b.roofCol, '#1e293b', 0.5);
    }

    // --- 3. TOKYO POCKET PARK ---
    addPoly([
      { x: -336, y: 111.5, z: 424 }, { x: -88, y: 111.5, z: 424 },
      { x: -88, y: 111.5, z: 616 }, { x: -336, y: 111.5, z: 616 }
    ], '#0a2318');

    // Park Stone Curb
    addPoly([
      { x: -340, y: 112, z: 420 }, { x: -230, y: 112, z: 420 },
      { x: -230, y: 102, z: 420 }, { x: -340, y: 102, z: 420 }
    ], '#374151', '#1f2937', 0.8);
    addPoly([
      { x: -190, y: 112, z: 420 }, { x: -85, y: 112, z: 420 },
      { x: -85, y: 102, z: 420 }, { x: -190, y: 102, z: 420 }
    ], '#374151', '#1f2937', 0.8);

    addPoly([
      { x: -85, y: 112, z: 420 }, { x: -85, y: 112, z: 500 },
      { x: -85, y: 102, z: 500 }, { x: -85, y: 102, z: 420 }
    ], '#283140', '#1f2937', 0.8);
    addPoly([
      { x: -85, y: 112, z: 540 }, { x: -85, y: 112, z: 620 },
      { x: -85, y: 102, z: 620 }, { x: -85, y: 102, z: 540 }
    ], '#283140', '#1f2937', 0.8);

    // Trees
    const parkTrees = [
      { x: -170, z: 460, trunkH: -30, topH: -130, c1: '#eab308', c2: '#ca8a04' },
      { x: -280, z: 470, trunkH: -35, topH: -145, c1: '#059669', c2: '#047857' },
      { x: -180, z: 570, trunkH: -30, topH: -135, c1: '#f472b6', c2: '#db2777' },
      { x: -290, z: 580, trunkH: -30, topH: -125, c1: '#ea580c', c2: '#c2410c' }
    ];

    parkTrees.forEach(t => {
      const cp = toCamSpace(t.x, 0, t.z);
      if (cp.z >= 12) {
        const cz = cp.z;
        const trunkPts = [
          projectRel({ x: cp.x - 3.5, y: 112, z: cz }),
          projectRel({ x: cp.x + 3.5, y: 112, z: cz }),
          projectRel({ x: cp.x + 2.5, y: t.trunkH + 5, z: cz }),
          projectRel({ x: cp.x - 2.5, y: t.trunkH + 5, z: cz })
        ];
        renderList.push({
          depth: cz + 0.2,
          svg: `<polygon points="${trunkPts.map(p => p.x.toFixed(1) + ',' + p.y.toFixed(1)).join(' ')}" fill="#451a03" />`
        });

        const r1 = 30;
        const r2 = 24;
        const midY = (t.trunkH + t.topH) / 2;

        const lowerPts = [
          projectRel({ x: cp.x - r1 * 0.85, y: t.trunkH + 8, z: cz }),
          projectRel({ x: cp.x + r1 * 0.85, y: t.trunkH + 8, z: cz }),
          projectRel({ x: cp.x + r1, y: midY + 8, z: cz }),
          projectRel({ x: cp.x + r1 * 0.7, y: midY - 12, z: cz }),
          projectRel({ x: cp.x - r1 * 0.7, y: midY - 12, z: cz }),
          projectRel({ x: cp.x - r1, y: midY + 8, z: cz })
        ];
        renderList.push({
          depth: cz + 0.1,
          svg: `<polygon points="${lowerPts.map(p => p.x.toFixed(1) + ',' + p.y.toFixed(1)).join(' ')}" fill="${t.c2}" stroke="${t.c1}" stroke-width="0.8" />`
        });

        const upperPts = [
          projectRel({ x: cp.x - r2, y: midY - 2, z: cz }),
          projectRel({ x: cp.x + r2, y: midY - 2, z: cz }),
          projectRel({ x: cp.x + r2 * 0.75, y: t.topH + 12, z: cz }),
          projectRel({ x: cp.x, y: t.topH, z: cz }),
          projectRel({ x: cp.x - r2 * 0.75, y: t.topH + 12, z: cz })
        ];
        renderList.push({
          depth: cz,
          svg: `<polygon points="${upperPts.map(p => p.x.toFixed(1) + ',' + p.y.toFixed(1)).join(' ')}" fill="${t.c1}" />`
        });
      }
    });

    // Stone Garden Lantern (Tōrō)
    const lx = -140, lz = 515;
    addPoly([
      { x: lx - 8, y: 112, z: lz }, { x: lx + 8, y: 112, z: lz },
      { x: lx + 6, y: 75, z: lz }, { x: lx - 6, y: 75, z: lz }
    ], '#4b5563');
    addPoly([
      { x: lx - 5.5, y: 75, z: lz }, { x: lx + 5.5, y: 75, z: lz },
      { x: lx + 5.5, y: 55, z: lz }, { x: lx - 5.5, y: 55, z: lz }
    ], '#f59e0b', '#d97706', 0.8, 'filter="url(#glow-amber)"');
    addPoly([
      { x: lx - 14, y: 55, z: lz }, { x: lx + 14, y: 55, z: lz },
      { x: lx, y: 42, z: lz }
    ], '#374151');

    // --- 4. VENDING MACHINES & INFRASTRUCTURE ---
    const vendings = [
      { x: 78, z: 140, col: '#dc2626', glow: '#fca5a5' },
      { x: 78, z: 180, col: '#0284c7', glow: '#7dd3fc' },
      { x: 78, z: 220, col: '#d97706', glow: '#fde047' }
    ];
    vendings.forEach(v => {
      addPoly([
        { x: v.x - 22, y: 111.6, z: v.z - 16 }, { x: v.x + 8, y: 111.6, z: v.z - 16 },
        { x: v.x + 8, y: 111.6, z: v.z + 16 }, { x: v.x - 22, y: 111.6, z: v.z + 16 }
      ], v.glow, 'none', 0, 'opacity="0.25"');

      addPoly([
        { x: v.x - 6, y: 112, z: v.z - 12 }, { x: v.x - 6, y: 112, z: v.z + 12 },
        { x: v.x - 6, y: 38, z: v.z + 12 }, { x: v.x - 6, y: 38, z: v.z - 12 }
      ], v.col, '#0b0f19', 1);

      addPoly([
        { x: v.x - 6.5, y: 80, z: v.z - 9 }, { x: v.x - 6.5, y: 80, z: v.z + 9 },
        { x: v.x - 6.5, y: 48, z: v.z + 9 }, { x: v.x - 6.5, y: 48, z: v.z - 9 }
      ], '#ffffff', '#38bdf8', 0.8, 'filter="url(#glow-cyan)"');
    });

    // Utility Poles
    const poles = [
      { x: -68, z: 290 }, { x: 68, z: 290 },
      { x: -68, z: 630 }, { x: 68, z: 630 }
    ];
    poles.forEach(p => {
      addPoly([
        { x: p.x - 2, y: 112, z: p.z }, { x: p.x + 2, y: 112, z: p.z },
        { x: p.x + 1.5, y: -240, z: p.z }, { x: p.x - 1.5, y: -240, z: p.z }
      ], '#334155');

      addPoly([
        { x: p.x - 18, y: -200, z: p.z }, { x: p.x + 18, y: -200, z: p.z },
        { x: p.x + 18, y: -205, z: p.z }, { x: p.x - 18, y: -205, z: p.z }
      ], '#475569');

      addPoly([
        { x: p.x - 7, y: -160, z: p.z }, { x: p.x + 7, y: -160, z: p.z },
        { x: p.x + 7, y: -185, z: p.z }, { x: p.x - 7, y: -185, z: p.z }
      ], '#1e293b', '#0f172a', 0.5);

      const lxP = p.x > 0 ? p.x - 18 : p.x + 18;
      addPoly([
        { x: p.x, y: -130, z: p.z }, { x: lxP, y: -140, z: p.z },
        { x: lxP, y: -143, z: p.z }, { x: p.x, y: -133, z: p.z }
      ], '#64748b');

      addPoly([
        { x: lxP - 30, y: 111.5, z: p.z - 30 }, { x: lxP + 30, y: 111.5, z: p.z - 30 },
        { x: lxP + 30, y: 111.5, z: p.z + 30 }, { x: lxP - 30, y: 111.5, z: p.z + 30 }
      ], '#fef08a', 'none', 0, 'opacity="0.16" filter="url(#glow-amber)"');
    });

    // Overhead Cables
    [[poles[0], poles[1]], [poles[2], poles[3]], [poles[0], poles[2]], [poles[1], poles[3]]].forEach(([p1, p2]) => {
      const c1 = toCamSpace(p1.x, -200, p1.z);
      const c2 = toCamSpace(p2.x, -200, p2.z);
      if (c1.z >= 12 && c2.z >= 12) {
        const p1_2d = projectRel(c1);
        const p2_2d = projectRel(c2);
        const midY = (p1_2d.y + p2_2d.y) / 2 + 15 * p1_2d.scale;
        const avgZ = (c1.z + c2.z) / 2;
        const p1x = p1_2d.x.toFixed(1);
        const p1y = p1_2d.y.toFixed(1);
        const p2x = p2_2d.x.toFixed(1);
        const p2y = p2_2d.y.toFixed(1);
        const midX = ((p1_2d.x + p2_2d.x) / 2).toFixed(1);
        const sw = Math.max(0.6, 1.6 * p1_2d.scale).toFixed(1);
        renderList.push({
          depth: avgZ,
          svg: `<path d="M ${p1x} ${p1y} Q ${midX} ${midY.toFixed(1)} ${p2x} ${p2y}" fill="none" stroke="#090d16" stroke-width="${sw}" opacity="0.8" />`
        });
      }
    });

    // --- 5. SOUTH APARTMENT ENTRANCE ---
    if (streetCam.z <= 140) {
      addPoly([
        { x: -50, y: 40, z: 12 }, { x: 50, y: 40, z: 12 },
        { x: 50, y: 32, z: 12 }, { x: -50, y: 32, z: 12 }
      ], '#0f172a', '#d4af37', 1.5);

      addPoly([
        { x: -45, y: 112, z: 14 }, { x: 45, y: 112, z: 14 },
        { x: 45, y: 42, z: 14 }, { x: -45, y: 42, z: 14 }
      ], '#0284c7', '#7dd3fc', 1, 'opacity="0.35"');
    }

    renderList.sort((a, b) => b.depth - a.depth);
    streetDynamicEl.innerHTML = renderList.map(item => item.svg).join('');

    // --- 6. RENDER MINIMAP ---
    if (streetMinimapContentEl) {
      const innerX = 10, innerY = 28, innerW = 160, innerH = 142;
      function toMap(wx, wz) {
        const nx = (wx + 450) / 900;
        const nz = wz / 850;
        return {
          x: innerX + nx * innerW,
          y: (innerY + innerH) - nz * innerH
        };
      }

      let mmSvg = '';
      // Roads
      const p0 = toMap(-60, 0);
      const p1 = toMap(60, 850);
      mmSvg += `<rect x="${p0.x.toFixed(1)}" y="${p1.y.toFixed(1)}" width="${(toMap(60, 0).x - p0.x).toFixed(1)}" height="${(p0.y - p1.y).toFixed(1)}" fill="#1e293b" />`;

      const sc0 = toMap(-420, 310);
      const sc1 = toMap(420, 400);
      mmSvg += `<rect x="${sc0.x.toFixed(1)}" y="${sc1.y.toFixed(1)}" width="${(toMap(420, 0).x - sc0.x).toFixed(1)}" height="${(sc0.y - sc1.y).toFixed(1)}" fill="#1e293b" />`;

      const nc0 = toMap(-420, 640);
      const nc1 = toMap(420, 730);
      mmSvg += `<rect x="${nc0.x.toFixed(1)}" y="${nc1.y.toFixed(1)}" width="${(toMap(420, 0).x - nc0.x).toFixed(1)}" height="${(nc0.y - nc1.y).toFixed(1)}" fill="#1e293b" />`;

      const wl0 = toMap(-420, 310);
      const wl1 = toMap(-340, 730);
      mmSvg += `<rect x="${wl0.x.toFixed(1)}" y="${wl1.y.toFixed(1)}" width="${(toMap(-340, 0).x - wl0.x).toFixed(1)}" height="${(wl0.y - wl1.y).toFixed(1)}" fill="#1e293b" />`;

      const el0 = toMap(340, 310);
      const el1 = toMap(420, 730);
      mmSvg += `<rect x="${el0.x.toFixed(1)}" y="${el1.y.toFixed(1)}" width="${(toMap(420, 0).x - el0.x).toFixed(1)}" height="${(el0.y - el1.y).toFixed(1)}" fill="#1e293b" />`;

      // Buildings
      streetBuildings.forEach(b => {
        const bp0 = toMap(b.x1, b.z1);
        const bp1 = toMap(b.x2, b.z2);
        mmSvg += `<rect x="${bp0.x.toFixed(1)}" y="${bp1.y.toFixed(1)}" width="${(toMap(b.x2, 0).x - bp0.x).toFixed(1)}" height="${(bp0.y - bp1.y).toFixed(1)}" fill="#0f172a" stroke="#334155" stroke-width="0.8" rx="1.5" />`;
      });

      // Park
      const pk0 = toMap(-340, 420);
      const pk1 = toMap(-80, 620);
      mmSvg += `<rect x="${pk0.x.toFixed(1)}" y="${pk1.y.toFixed(1)}" width="${(toMap(-80, 0).x - pk0.x).toFixed(1)}" height="${(pk0.y - pk1.y).toFixed(1)}" fill="#064e3b" stroke="#10b981" stroke-width="0.8" rx="1.5" />`;

      // Landmarks with Labels
      const landmarks = [
        { x: 0, z: 15, col: '#eab308', lbl: 'LOBBY', dx: 5, dy: -4 },
        { x: 140, z: 520, col: '#38bdf8', lbl: 'KONBINI', dx: 5, dy: 2 },
        { x: 140, z: 175, col: '#f43f5e', lbl: 'RAMEN', dx: 5, dy: 2 },
        { x: -140, z: 175, col: '#fbbf24', lbl: 'CAFE', dx: -28, dy: 2 },
        { x: -210, z: 520, col: '#34d399', lbl: 'PARK', dx: 5, dy: 2 }
      ];
      landmarks.forEach(lm => {
        const lp = toMap(lm.x, lm.z);
        mmSvg += `<circle cx="${lp.x.toFixed(1)}" cy="${lp.y.toFixed(1)}" r="2.8" fill="${lm.col}" />`;
        mmSvg += `<text x="${(lp.x + lm.dx).toFixed(1)}" y="${(lp.y + lm.dy).toFixed(1)}" fill="${lm.col}" font-size="7" font-weight="bold" font-family="'Segoe UI', monospace" opacity="0.9">${lm.lbl}</text>`;
      });

      // Player indicator & Vision Cone
      const plP = toMap(streetCam.x, streetCam.z);
      const fovLen = 14;
      const ang1 = streetCam.theta - 0.42;
      const ang2 = streetCam.theta + 0.42;
      const fovX1 = plP.x + Math.sin(ang1) * fovLen;
      const fovY1 = plP.y - Math.cos(ang1) * fovLen;
      const fovX2 = plP.x + Math.sin(ang2) * fovLen;
      const fovY2 = plP.y - Math.cos(ang2) * fovLen;

      mmSvg += `<polygon points="${plP.x.toFixed(1)},${plP.y.toFixed(1)} ${fovX1.toFixed(1)},${fovY1.toFixed(1)} ${fovX2.toFixed(1)},${fovY2.toFixed(1)}" fill="#38bdf8" opacity="0.4" />`;
      mmSvg += `<circle cx="${plP.x.toFixed(1)}" cy="${plP.y.toFixed(1)}" r="3.2" fill="#38bdf8" stroke="#ffffff" stroke-width="1" />`;

      streetMinimapContentEl.innerHTML = mmSvg;
    }
  }

  // Game Loop
  function gameLoop() {
    if (!state.modalOpen && !state.transitioning) {
      if (state.currentZone === 'street') {
        // Turning controls: A/Left and D/Right
        if (state.keys.a || state.keys.left) {
          streetCam.theta -= streetCam.turnSpeed;
          if (streetCam.theta < -Math.PI) streetCam.theta += Math.PI * 2;
        }
        if (state.keys.d || state.keys.right) {
          streetCam.theta += streetCam.turnSpeed;
          if (streetCam.theta > Math.PI) streetCam.theta -= Math.PI * 2;
        }

        // Movement controls: W/Up (forward) and S/Down (backward) along theta
        let moveDir = 0;
        if (state.keys.w || state.keys.up) moveDir += 1;
        if (state.keys.s || state.keys.down) moveDir -= 1;

        if (moveDir !== 0) {
          const step = moveDir * streetCam.speed;
          const nextX = streetCam.x + Math.sin(streetCam.theta) * step;
          const nextZ = streetCam.z + Math.cos(streetCam.theta) * step;

          // Wall sliding collision
          if (!isStreetObstacle(nextX, streetCam.z)) {
            streetCam.x = nextX;
          }
          if (!isStreetObstacle(streetCam.x, nextZ)) {
            streetCam.z = nextZ;
          }

          // Clamp to neighbourhood boundaries
          streetCam.x = Math.max(-430, Math.min(410, streetCam.x));
          streetCam.z = Math.max(20, Math.min(840, streetCam.z));

          streetCam.walkCycle += 0.22;
        }

        // Update skyline 360-degree pan
        if (streetSkyPanEl) {
          const panX = -((streetCam.theta / (Math.PI * 2) * 960) % 960);
          streetSkyPanEl.setAttribute('transform', 'translate(' + panX.toFixed(1) + ', 0)');
        }

        // Apartment Entrance Prompt & State when near (X near 0, Z <= 95)
        const nearEntrance = Math.abs(streetCam.x) <= 85 && streetCam.z <= 95;
        if (promptStreetLobby) {
          promptStreetLobby.style.display = nearEntrance ? 'block' : 'none';
        }
        if (nearEntrance) {
          state.activeDoor = {
            id: 'street-to-lobby',
            targetZone: 'lobby',
            spawnX: 480,
            spawnY: 480,
            sound: 'door'
          };
        } else if (state.activeDoor && state.activeDoor.id === 'street-to-lobby') {
          state.activeDoor = null;
        }

        if (streetHudActionEl) {
          if (nearEntrance) {
            streetHudActionEl.textContent = '[E] RE-ENTER LOBBY';
            streetHudActionEl.setAttribute('fill', '#facc15');
          } else {
            streetHudActionEl.textContent = 'Explore (Walk Back to Enter)';
            streetHudActionEl.setAttribute('fill', '#64748b');
          }
        }

        renderStreet3D();
      } else {
        let mx = 0;
        let my = 0;

        if (state.keys.w || state.keys.up) my -= 1;
        if (state.keys.s || state.keys.down) my += 1;
        if (state.keys.a || state.keys.left) mx -= 1;
        if (state.keys.d || state.keys.right) mx += 1;

        state.isMoving = (mx !== 0 || my !== 0);

      if (state.isMoving) {
        const length = Math.sqrt(mx * mx + my * my);
        mx = (mx / length) * state.speed;
        my = (my / length) * state.speed;

        if (Math.abs(mx) > Math.abs(my)) {
          state.facing = mx > 0 ? 'right' : 'left';
        } else {
          state.facing = my > 0 ? 'down' : 'up';
        }
        updateCharacterFacing(state.facing);

        if (!checkCollision(state.x + mx, state.y)) {
          state.x += mx;
        }
        if (!checkCollision(state.x, state.y + my)) {
          state.y += my;
        }

        state.walkCycle += 0.22;
        const legSwing = Math.sin(state.walkCycle) * 7;
        const armSwing = Math.cos(state.walkCycle) * 6;
        const headBob = Math.abs(Math.sin(state.walkCycle)) * 1.5;

        // Front / Back Walk Dynamics
        legLEl.setAttribute('y', 14 + legSwing);
        shoeLEl.setAttribute('transform', `translate(0, ${legSwing})`);
        legREl.setAttribute('y', 14 - legSwing);
        shoeREl.setAttribute('transform', `translate(0, ${-legSwing})`);
        armLEl.setAttribute('transform', `translate(0, ${-armSwing})`);
        armREl.setAttribute('transform', `translate(0, ${armSwing})`);
        headEl.setAttribute('transform', `translate(0, ${-18 + headBob})`);

        // Dedicated Side Profile Walk Dynamics (Natural Stride Along X & Y)
        const strideX = Math.sin(state.walkCycle) * 3.5;
        const liftY = Math.abs(Math.sin(state.walkCycle)) * 1.5;
        const armStrideX = Math.cos(state.walkCycle) * 3.0;

        if (state.facing === 'right') {
          if (sideLegNearREl) sideLegNearREl.setAttribute('transform', `translate(${strideX}, ${strideX > 0 ? -liftY : 0})`);
          if (sideLegFarREl) sideLegFarREl.setAttribute('transform', `translate(${-strideX}, ${-strideX > 0 ? -liftY : 0})`);
          if (sideArmNearREl) sideArmNearREl.setAttribute('transform', `translate(${-armStrideX}, 0)`);
          if (sideArmFarREl) sideArmFarREl.setAttribute('transform', `translate(${armStrideX}, 0)`);
          if (sideHeadREl) sideHeadREl.setAttribute('transform', `translate(0, ${-18 + headBob})`);
        } else if (state.facing === 'left') {
          if (sideLegNearLEl) sideLegNearLEl.setAttribute('transform', `translate(${strideX}, ${strideX > 0 ? -liftY : 0})`);
          if (sideLegFarLEl) sideLegFarLEl.setAttribute('transform', `translate(${-strideX}, ${-strideX > 0 ? -liftY : 0})`);
          if (sideArmNearLEl) sideArmNearLEl.setAttribute('transform', `translate(${-armStrideX}, 0)`);
          if (sideArmFarLEl) sideArmFarLEl.setAttribute('transform', `translate(${armStrideX}, 0)`);
          if (sideHeadLEl) sideHeadLEl.setAttribute('transform', `translate(0, ${-18 + headBob})`);
        }
      } else {
        // Idle State: Reset all limbs to crisp standing alignment
        legLEl.setAttribute('y', 14);
        shoeLEl.removeAttribute('transform');
        legREl.setAttribute('y', 14);
        shoeREl.removeAttribute('transform');
        armLEl.removeAttribute('transform');
        armREl.removeAttribute('transform');
        headEl.setAttribute('transform', 'translate(0, -18)');

        if (sideLegNearREl) sideLegNearREl.removeAttribute('transform');
        if (sideLegFarREl) sideLegFarREl.removeAttribute('transform');
        if (sideArmNearREl) sideArmNearREl.removeAttribute('transform');
        if (sideArmFarREl) sideArmFarREl.removeAttribute('transform');
        if (sideHeadREl) sideHeadREl.setAttribute('transform', 'translate(0, -18)');

        if (sideLegNearLEl) sideLegNearLEl.removeAttribute('transform');
        if (sideLegFarLEl) sideLegFarLEl.removeAttribute('transform');
        if (sideArmNearLEl) sideArmNearLEl.removeAttribute('transform');
        if (sideArmFarLEl) sideArmFarLEl.removeAttribute('transform');
        if (sideHeadLEl) sideHeadLEl.setAttribute('transform', 'translate(0, -18)');
      }

      updateProximity();
      }
    }

    if (state.currentZone !== 'street' && playerEl) {
      playerEl.setAttribute('transform', `translate(${state.x}, ${state.y})`);
    }

    if (!isGamePaused) {
      requestAnimationFrame(gameLoop);
    }
  }

  let isGamePaused = false;
  window.addEventListener('message', (e) => {
    if (e.data === 'pause-game') {
      isGamePaused = true;
    } else if (e.data === 'resume-game') {
      if (isGamePaused) {
        isGamePaused = false;
        requestAnimationFrame(gameLoop);
      }
    }
  });

  updateCharacterFacing('down');
  requestAnimationFrame(gameLoop);
})();
